import{_ as t,o as a,c as n,ak as r}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy Game Design Document","description":"Version 2.0 • October 22, 2026 • Design proposal for owner review","frontmatter":{"title":"Chainy Game Design Document","description":"Version 2.0 • October 22, 2026 • Design proposal for owner review","source":"docs/game-design-v2-gameplay-first.md","category":"Other documents","sourceUpdated":"2026-10-22T22:46:54+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/game-design-v2-gameplay-first.md","filePath":"content/docs/game-design-v2-gameplay-first.md"}'),i={name:"content/docs/game-design-v2-gameplay-first.md"};function o(s,e,d,c,l,h){return a(),n("div",null,[...e[0]||(e[0]=[r('<div><h1 id="chainy-game-design-document">Chainy Game Design Document<a class="header-anchor" href="#chainy-game-design-document" aria-label="Link to this section">​</a></h1><h2 id="gameplay-first-edition">Gameplay First Edition<a class="header-anchor" href="#gameplay-first-edition" aria-label="Link to this section">​</a></h2><p>Version 2.0 • October 22, 2026 • Design proposal for owner review</p><p><strong>An offline island-restoration adventure for learning Web3, Blockchain and AI.</strong></p><p>The player helps residents restore island services, uses a fictional digital economy, repairs a damaged local blockchain record, and teaches and checks an AI helper. Learning happens through consequential actions; short quizzes and vocabulary activities support those actions.</p><p><strong>November 10 recommendation:</strong> deliver one complete Web3 restoration quest and one Blockchain repair challenge with dependable local saving. Add one AI training-and-test activity only after these pass Android checks. A broader three-world introduction is a stretch target, not a promise of 50 percent completion.</p><p>The owner reports that movement and dialogue are currently playable. The lead developer reports availability of up to 16–18 hours per day from October 23 through November 21. Neither statement is an independently tested build result. Estimates in Section 7 use focused implementation hours, not all available waking hours.</p><p>Prepared for Sherwin’s design decisions, Christian’s technical validation, Sean’s authored project documentation, Luis’s production art and Miguel’s UI implementation. This versioned gameplay-first review edition is stored alongside the current project documents; adoption into the canonical GDD, task board, manuscript or game code remains an owner decision.</p><p>All illustrated game screens are design concepts, not screenshots of a playable build. Generated artwork is not an import-ready Unity asset kit.</p><p>&lt;!-- page --&gt;</p><h2 id="contents">Contents<a class="header-anchor" href="#contents" aria-label="Link to this section">​</a></h2><ol><li>Game objectives and brief</li><li>Gameplay</li><li>Game world</li><li>Graphics and art style</li><li>Mechanics</li><li>Characters</li><li>Project plan and November 10 feasibility</li><li>References and template adaptation</li><li>Bibliography</li></ol><p>This edition follows the supplied <em>Games Design Document — Project Vanishing</em> as its main structural reference: brief, gameplay and controls, world and locations, art and GUI development, storyboard and sample narrative, sound, systems, characters, production plan and sources. Chainy’s own learning requirements replace that example’s combat, weapon progression, reputation and PC controls.</p><h3 id="reading-the-scope-labels">Reading the scope labels<a class="header-anchor" href="#reading-the-scope-labels" aria-label="Link to this section">​</a></h3><p><strong>CORE</strong> means the recommended November 10 delivery boundary, subject to the first Android checkpoint. <strong>STRETCH</strong> means work admitted only after the core passes. <strong>FULL</strong> means retained in the full experience but not promised for November 10. <strong>LATER SERVICE</strong> means teacher provisioning, collection or distribution work deferred behind gameplay.</p><p>These labels are delivery recommendations, not evidence that a feature is complete. The school’s completion formula is unknown. No task count, illustration, estimated hour or chapter count establishes its required percentage.</p><h3 id="main-changes-from-the-previous-proposal">Main changes from the previous proposal<a class="header-anchor" href="#main-changes-from-the-previous-proposal" aria-label="Link to this section">​</a></h3><ul><li>Keep the three-world journey, named guides and twelve hands-on concepts.</li><li>Put the playable restoration loop ahead of the teacher-service platform.</li><li>Keep local saving in the core: it is essential gameplay, not optional analytics work.</li><li>Replace a broad pre-beta wish list with explicit gates, recovery rules and fallback scope.</li><li>Preserve the full AI idea, but sequence the small example-based classifier before the assistant and agent exercises.</li><li>Separate the Blockchain repair exercise from the existing BlockMatch mini-game. They are not interchangeable names or implementations.</li></ul><p>&lt;!-- page --&gt;</p><h1 id="1-game-objectives-and-brief">1 Game objectives and brief<a class="header-anchor" href="#1-game-objectives-and-brief" aria-label="Link to this section">​</a></h1><h2 id="11-game-brief">1.1 Game brief<a class="header-anchor" href="#11-game-brief" aria-label="Link to this section">​</a></h2><p>Chainy is a single-player, offline Unity/C# Android learning adventure for learners aged 12–17. It uses a fixed orthographic isometric view, compact low-poly environments, touchscreen movement and contextual interaction. English is the first language. No real cryptocurrency, real wallet, public blockchain, financial account or cloud AI service is required.</p><p>The intended player experience is curiosity followed by useful action: “I need to restore the workshop; I can earn a reward, buy a tool, check the ownership record and use the tool.” Definitions explain an action the learner has just encountered instead of becoming the whole activity.</p><p>One personal phone per learner is the intended school model. Once enrolled in the full product, play and saving do not depend on the teacher remaining nearby. The November gameplay build uses a clearly identified local demo profile until the later enrollment service exists. It must not present an unimplemented voucher screen as a working security boundary.</p><h2 id="12-narrative-brief">1.2 Narrative brief<a class="header-anchor" href="#12-narrative-brief" aria-label="Link to this section">​</a></h2><p>Island services have stopped working. The workshop needs light and supplies; the beacon’s local record display has been corrupted; the assistance center gives unreliable advice. Residents ask the Explorer for practical help.</p><p>Sean introduces how to use the island’s digital economy. Matthew helps reconstruct verified records at the beacon. Lee helps train and evaluate an advisory bot. Each restoration visibly changes the world: a workshop lights up, a beacon shines, then a dispatch center resumes supervised service.</p><p>This is a helpful adventure, not a combat game. The motivation is restoration and responsibility, not trading profit, punishment for mistakes or competition over wealth.</p><h2 id="13-learning-objectives">1.3 Learning objectives<a class="header-anchor" href="#13-learning-objectives" aria-label="Link to this section">​</a></h2><table><thead><tr><th>World</th><th>Learner should be able to do</th><th>Evidence in play</th></tr></thead><tbody><tr><td>Web3</td><td>Distinguish access, ownership and payment; explain a fee; use a conditional program</td><td>Review a purchase, authorize it, inspect its record and use owned equipment</td></tr><tr><td>Blockchain</td><td>Distinguish linked records, validation and agreement; identify stale or altered data</td><td>Repair a local sequence from a trusted reference and explain a mismatch</td></tr><tr><td>AI</td><td>Explain examples, predictions and testing; recognize limits; verify advice</td><td>Change training examples, test fresh requests and require evidence before action</td></tr></tbody></table><p>Completion is not automatically mastery. A correct answer after a hint is useful practice, but different evidence from an unassisted first response or a fresh transfer question.</p><h2 id="14-design-pillars-and-exclusions">1.4 Design pillars and exclusions<a class="header-anchor" href="#14-design-pillars-and-exclusions" aria-label="Link to this section">​</a></h2><p>Every required concept should support a meaningful player choice, visible system response and understandable explanation. A term may be a tool, station, action, cost or record; not everything should become collectible loot.</p><p>Keep journeys short and landmarks readable. Reuse one interaction grammar across worlds: inspect, decide, confirm, see the result and save. Let mistakes invite explanation and retry without permanently losing essential resources.</p><p>Excluded from this version: multiplayer, real payments, speculation, live exchanges, public-chain deployment, real seed phrases, live generative chat, procedural open worlds, combat, skill trees, complex NPC schedules and mandatory online student accounts.</p><p>&lt;!-- page --&gt;</p><h1 id="2-gameplay">2 Gameplay<a class="header-anchor" href="#2-gameplay" aria-label="Link to this section">​</a></h1><h2 id="21-overview">2.1 Overview<a class="header-anchor" href="#21-overview" aria-label="Link to this section">​</a></h2><p>Full-product flow: first-time Teacher or Student selection → authorized setup → Play → world selection → exploration → guide or resident → quest action → feedback → saved checkpoint.</p><p>Gameplay-milestone flow: local demo profile → Play → world selection → the same offline quest loop. The temporary profile route is explicitly a demonstration boundary, not a replacement for the full school enrollment requirement.</p><p>Web3 opens first. Completing its required chapter unlocks Blockchain; completing Blockchain unlocks AI. Optional encyclopedia discoveries and supporting mini-games do not require 100 percent collection before progression. Completed worlds remain revisitable.</p><p>For the milestone, a versioned <strong>demo quest list</strong> defines its shorter chapter. Its completion must be labelled “intro chapter complete,” not completion of every full-world quest. Future content can add new quests without erasing previously earned records or claiming that an unplayed full chapter was mastered.</p><h3 id="core-interaction-loop">Core interaction loop<a class="header-anchor" href="#core-interaction-loop" aria-label="Link to this section">​</a></h3><ol><li>See the current objective and location hint.</li><li>Explore a short route and inspect a relevant object or guide.</li><li>Receive enough explanation to make a decision.</li><li>Perform a useful action: pay, verify, repair or test.</li><li>See what changed and why it succeeded or failed.</li><li>Commit the checkpoint, then enable the next objective.</li></ol><h2 id="22-controls-and-layout">2.2 Controls and layout<a class="header-anchor" href="#22-controls-and-layout" aria-label="Link to this section">​</a></h2><p>Landscape orientation is the proposed implementation target. Keep the approved fixed orthographic camera at roughly 35–45 degrees; avoid camera-rotation controls for the milestone.</p><table><thead><tr><th>Input</th><th>Action</th><th>Required behavior</th></tr></thead><tbody><tr><td>Left thumb joystick</td><td>Move</td><td>Stop during dialogue, modal UI, loading or saving transitions</td></tr><tr><td>Right contextual button</td><td>Interact</td><td>Show the nearby target and action; do not activate a distant object</td></tr><tr><td>Quest and encyclopedia buttons</td><td>Open overlay</td><td>Preserve the world and current objective on closing</td></tr><tr><td>Tap card, then destination</td><td>Place or compare record</td><td>Alternative to dragging; selected state uses more than color</td></tr><tr><td>Back or pause</td><td>Pause or close current layer</td><td>Never silently discard a confirmed purchase or completed quest</td></tr></tbody></table><p>No jumping, combat, free-camera control or platforming precision is required. Test legibility, thumb reach and safe margins on a named small-screen phone. A proposed 48 dp minimum touch target is a design starting point, not a claim that the current UI meets it.</p><h2 id="23-failure-and-return-paths">2.3 Failure and return paths<a class="header-anchor" href="#23-failure-and-return-paths" aria-label="Link to this section">​</a></h2><p>Insufficient funds show the missing amount and a route to earn the required coins. A wrong answer reveals reasoning and allows retry. An early item remains collected. A cancelled purchase has no effect. A submitted transaction cannot be submitted twice by repeated taps. A save failure keeps the last good checkpoint and offers retry.</p><p>After closing and reopening the game, the active objective, completed actions, balances, owned items and restored scene must agree. The success animation alone is not proof that a save succeeded.</p><p>&lt;!-- page --&gt;</p><h1 id="3-game-world">3 Game world<a class="header-anchor" href="#3-game-world" aria-label="Link to this section">​</a></h1><h2 id="31-world-structure">3.1 World structure<a class="header-anchor" href="#31-world-structure" aria-label="Link to this section">​</a></h2><p>The full experience has three ordered worlds. For early production they may be three compact scenes assembled from the same island kit, not three large bespoke open worlds. Each scene needs a safe arrival point, a guide visible from the arrival route, a few readable stations and a visible restoration target.</p><p><strong>Web3 harbor → Blockchain beacon → AI assistance center.</strong> The first world teaches use, the second teaches record integrity, and the third teaches prediction and verification. The same lantern transaction provides continuity across all three.</p><table><thead><tr><th>Location</th><th>Main landmarks</th><th>Restoration outcome</th></tr></thead><tbody><tr><td>Web3 harbor</td><td>Sean’s arrival plaza, resident, merchant, workshop, exchange and repair terminal</td><td>Workshop and harbor services reopen</td></tr><tr><td>Blockchain beacon</td><td>Matthew’s checkpoint console, damaged local display, verified reference station, stale-node station</td><td>Local record repairs and beacon returns</td></tr><tr><td>AI center</td><td>Lee’s example desk, practice test desk, evidence console, dispatch dock</td><td>A supervised helper can assist residents</td></tr></tbody></table><p>Place optional discovery objects beside required paths. Use signs, silhouettes and quest markers together; do not make a new learner hunt across the island for the tutorial. Exits explain the specific unmet main objective.</p><h2 id="32-web3-harbor">3.2 Web3 harbor<a class="header-anchor" href="#32-web3-harbor" aria-label="Link to this section">​</a></h2><p><img src="/Chainy-Docs/attachments/docs/media/gdd/gameplay-first/web3-world.png" alt="Web3 harbor world concept"></p><p><em>Concept target: a short route from Sean and the resident to the merchant and dark workshop. Scene dressing is illustrative; use the smallest production layout that supports the quest.</em></p><p>The learner should care about the lantern because it enables restoration, not because an NPC demands that the word “NFT” be memorized. Sean links the tool, the payment and the ownership record after the player encounters them.</p><p>&lt;!-- page --&gt;</p><h3 id="web3-quest-sequence">Web3 quest sequence<a class="header-anchor" href="#web3-quest-sequence" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Quest</th><th>Action and feedback</th><th>Scope</th></tr></thead><tbody><tr><td>W01 Arrive and meet Sean</td><td>Walk to the visible guide; open quest log and encyclopedia; inspect the wallet and a shareable receiving address</td><td>CORE</td></tr><tr><td>W02 Help the resident</td><td>Collect one required repair component; return it; receive 12 fictional Chain Coins once</td><td>CORE</td></tr><tr><td>W03 Buy the lantern</td><td>Inspect Lantern #014; review price 8 plus fee 1; sign; see pending then confirmed; balance becomes 3</td><td>CORE</td></tr><tr><td>W04 Light the workshop</td><td>Verify ownership; equip the lantern for free; activate the mechanism; see the workshop restored and save</td><td>CORE</td></tr><tr><td>W05 Supply the builders</td><td>Exchange coins for issued Builder Tokens at a displayed tutorial quote; preserve native fee funds</td><td>FULL</td></tr><tr><td>W06 Claim the repair agreement</td><td>Deliver the required supplies; submit the terminal’s completion evidence; call a conditional reward once</td><td>FULL</td></tr><tr><td>W07 Recover access</td><td>Restore a fictional wallet device using its previously secured in-game backup; inspect unchanged ownership</td><td>FULL</td></tr><tr><td>W08 Reopen the harbor</td><td>Combine a new purchase, ownership check and repair evidence in a transfer-of-learning challenge</td><td>FULL</td></tr></tbody></table><p>For W01–W04 the basic purchase itself illustrates a simple programmed condition: sufficient funds and an available item are required before the atomic exchange. The separate resident agreement in W06 adds external completion evidence and should not be confused with merely choosing “yes” in dialogue.</p><p>The resident’s 12-coin reward is a one-time quest allocation from the simulation, not a lesson claiming that all cryptocurrency is created by completing errands. There are no optional purchases before this required transaction in the core slice. Later shopping needs a tested resource-recovery route.</p><h3 id="example-narrative-and-teaching-beat">Example narrative and teaching beat<a class="header-anchor" href="#example-narrative-and-teaching-beat" aria-label="Link to this section">​</a></h3><p>Sean: “The workshop needs a lantern. Help our neighbor first, then check what the merchant is asking.”</p><p>Merchant: “Lantern #014 costs 8 Chain Coins. This transaction also needs a network fee of 1.”</p><p>Review prompt: “You have 12. How many remain after this transaction?” A wrong answer highlights the price and fee separately, then permits another try without charging the player.</p><p>After confirmation, Sean asks the learner to open the ownership record and find the lantern. At the workshop, the learner equips it without a new payment. A final new example asks whether reading the encyclopedia also costs gas. The explanation identifies which actions change the simulated network state.</p><p>A correct mathematical answer alone is insufficient: the learner must also see the item and payment change together, and distinguish the ledger record from the wallet interface.</p><p>&lt;!-- page --&gt;</p><h2 id="33-blockchain-beacon">3.3 Blockchain beacon<a class="header-anchor" href="#33-blockchain-beacon" aria-label="Link to this section">​</a></h2><p><img src="/Chainy-Docs/attachments/docs/media/gdd/gameplay-first/blockchain-world.png" alt="Blockchain beacon world concept"></p><p><em>Concept target: repair one damaged local station using a trusted reference. Other stations represent local simulated copies on the same phone, not connected student devices.</em></p><p>The beacon’s local copy is damaged. Matthew can access a trusted checkpoint and verified reference history. The learner repairs the local display and record; they do not rewrite accepted global history.</p><h3 id="blockchain-quest-sequence">Blockchain quest sequence<a class="header-anchor" href="#blockchain-quest-sequence" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Quest</th><th>Action and feedback</th><th>Scope</th></tr></thead><tbody><tr><td>B01 Read the familiar record</td><td>Inspect the confirmed Web3 purchase, including 8-coin price, 1-coin fee and Lantern #014 transfer</td><td>CORE</td></tr><tr><td>B02 Restore the sequence</td><td>Place three subsequent display blocks after a trusted checkpoint by their previous-block references</td><td>CORE</td></tr><tr><td>B03 Reject the altered copy</td><td>Compare a changed 6-coin local payment with the verified 8-coin original; identify the broken reference</td><td>CORE</td></tr><tr><td>B04 Synchronize a stale node</td><td>Load verified missing blocks into a behind-but-not-tampered copy</td><td>FULL</td></tr><tr><td>B05 Help validate a batch</td><td>Check authorization, funds, ownership and repeated transactions before a simulated network decision</td><td>FULL</td></tr><tr><td>B06 Compare mining and validators</td><td>Operate a bounded nonce-search demonstration; contrast it with the main validator workflow</td><td>FULL</td></tr><tr><td>B07 Restore the beacon</td><td>Recheck the local checkpoint, restore the light and explain the repair</td><td>CORE for demo; FULL synthesis later</td></tr></tbody></table><p>B02 and B03 use one bounded scenario, not a general block editor. The verified reference remains read-only. Blocks may contain multiple records. Timestamps and colors may aid reading but cannot be the reason a sequence is accepted.</p><p>An out-of-date copy is not necessarily dishonest. A changed copy that breaks a trusted reference is a different fault. If no trustworthy reference exists, the correct explanation is that the original is not established, not “the player chooses which history is true.”</p><p>&lt;!-- page --&gt;</p><h2 id="34-ai-assistance-center">3.4 AI assistance center<a class="header-anchor" href="#34-ai-assistance-center" aria-label="Link to this section">​</a></h2><p><img src="/Chainy-Docs/attachments/docs/media/gdd/gameplay-first/ai-world.png" alt="AI assistance center world concept"></p><p><em>Concept target: a teaching desk, separate testing area and supervised dispatch station. The learning model and later assistant are distinct systems.</em></p><p>Lee’s helper examines fictional transaction requests. Blockchain checks whether a transaction meets network rules; the helper offers fallible advice about whether a person should review the request. A valid signature does not prove that a request is wise or honest.</p><h3 id="ai-quest-sequence">AI quest sequence<a class="header-anchor" href="#ai-quest-sequence" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Quest</th><th>Action and feedback</th><th>Scope</th></tr></thead><tbody><tr><td>A01 Teach with examples</td><td>Read contextual evidence; label a small example set Routine or Review; fit an explainable tiny classifier</td><td>STRETCH</td></tr><tr><td>A02 Test unfamiliar requests</td><td>Predict what the bot will say; run new cases; inspect mistakes; correct an example and practice again</td><td>STRETCH</td></tr><tr><td>A03 Make the final check</td><td>Use a reserved fresh set; explain one limitation; restore the teaching desk</td><td>STRETCH</td></tr><tr><td>A04 Ask and verify</td><td>Build a request with goal, context and constraints; check an authored assistant response against the ledger</td><td>FULL</td></tr><tr><td>A05 Supervise dispatch</td><td>Inspect a proposed recipient, item and cost; approve or reject; recheck changed conditions</td><td>FULL</td></tr></tbody></table><p>The recommended first implementation is a small nearest-neighbor classifier over explicitly defined features, not a neural network, cloud chatbot or financial fraud engine. It must actually depend on the learner’s labelled examples. If outputs are authored branches, label the activity an AI demonstration instead of a trained model.</p><p>Use synthetic requests only. Include a legitimate large community purchase and a suspicious small request so “large amount means bad” is visibly inadequate. An unknown case can require human review. The bot never spends without approval.</p><p>A01–A03 can form a short standalone intro chapter after the core passes. A04–A05 add modern assistant and agent concepts later; they are not required to make the first classifier lesson educationally honest.</p><p>&lt;!-- page --&gt;</p><h1 id="4-graphics-and-art-style">4 Graphics and art style<a class="header-anchor" href="#4-graphics-and-art-style" aria-label="Link to this section">​</a></h1><h2 id="41-art-direction-and-production-boundaries">4.1 Art direction and production boundaries<a class="header-anchor" href="#41-art-direction-and-production-boundaries" aria-label="Link to this section">​</a></h2><p>Retain the approved fixed isometric, restrained low-poly direction. Use faceted silhouettes, angular ruins, simple material surfaces, sparse painterly detail, readable long shadows and controlled glow. Water and terrain should frame paths rather than create visually busy routes.</p><p>The approved Explorer has blue hair and yellow clothing; friendly robot guides use white bodies and dark screen faces with cyan expressions. Apply the same faceted treatment to characters and environments. Do not return to the superseded rounded toy or bright voxel-diorama look.</p><p>Tunic is a camera, material-density and composition reference only. Do not copy its maps, characters, props, icons or HUD. The supplied Project Vanishing document controls the GDD’s organization, not Chainy’s camera, genre or art assets.</p><h3 id="minimum-production-kit">Minimum production kit<a class="header-anchor" href="#minimum-production-kit" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Asset family</th><th>November candidate</th><th>Later expansion</th></tr></thead><tbody><tr><td>World pieces</td><td>Shared ground, wall, path, stair, bridge, water and foliage pieces</td><td>More regional dressing after performance checks</td></tr><tr><td>Interaction stations</td><td>Merchant, workshop mechanism, ledger console, beacon</td><td>Exchange, mining, recovery and AI dispatch stations</td></tr><tr><td>Characters</td><td>Existing Explorer plus one reusable robot rig with named variants</td><td>Extra resident silhouettes and reactions</td></tr><tr><td>Inventory</td><td>Repair component, lantern, wallet icon and coin symbol</td><td>Builder Token, supplies and contract evidence icons</td></tr><tr><td>Feedback</td><td>Objective marker, selection outline, success/error symbol, restoration light</td><td>Extra cosmetic animation only after core acceptance</td></tr></tbody></table><p>Luis provides source files, export previews, scale/origin notes, materials, animation lists and provenance. Miguel implements interactive UI. Christian validates the imported scene on Android. Final polygon counts, texture sizes, memory and package budgets follow a measured representative scene; a 4 GB RAM phone does not give the game all 4 GB.</p><h2 id="42-interface-design">4.2 Interface design<a class="header-anchor" href="#42-interface-design" aria-label="Link to this section">​</a></h2><p>The exploration HUD shows one short objective, quest/encyclopedia access, movement and interaction. Keep additional panels contextual. The wallet has Balances, Items and Activity views. Display native Chain Coin separately from Builder Token and unique equipment.</p><p>Dialogue remains over the live isometric scene: wide bottom panel, Explorer portrait on the left, speaker portrait on the right and centered choices above. Disable movement and world interaction while the overlay is active. Neutral choices must not reveal the correct answer through color before selection.</p><p>All essential feedback works with sound off and includes text or an icon as well as color. Let learners control dialogue pacing, reopen explanations and use tap-to-place instead of dragging. Keep decorative hex strings secondary to understandable sender, recipient, amount and status fields.</p><p>&lt;!-- page --&gt;</p><h2 id="43-storyboard-and-gui-development">4.3 Storyboard and GUI development<a class="header-anchor" href="#43-storyboard-and-gui-development" aria-label="Link to this section">​</a></h2><p><img src="/Chainy-Docs/attachments/docs/media/gdd/gameplay-first/navigation-journal.png" alt="World selection quest log and encyclopedia concepts"></p><p><em>Three separate screen studies, not three panels shown simultaneously on a phone. The quest log separates a current goal, its next action and completed history; encyclopedia stages record learning activities rather than a mastery percentage.</em></p><table><thead><tr><th>Panel</th><th>What the player sees</th><th>What the system must do</th></tr></thead><tbody><tr><td>1 Play and worlds</td><td>Web3 available; Blockchain and AI have specific unlock labels</td><td>Resume the active demo checkpoint or begin the tutorial</td></tr><tr><td>2 Arrival</td><td>Sean visible near a short path; one objective</td><td>Teach movement and interaction without a long search</td></tr><tr><td>3 Explain</td><td>Live scene behind the dialogue overlay</td><td>Capture only dialogue input; add the basic encyclopedia entry</td></tr><tr><td>4 Review purchase</td><td>Item, price, fee, total and remaining balance</td><td>Permit cancel; reject invalid input before submission</td></tr><tr><td>5 Confirmed result</td><td>Lantern ownership and activity record; new balance</td><td>Commit related state once before showing saved success</td></tr><tr><td>6 Restoration</td><td>Workshop illuminates and route updates</td><td>Award completion once; unlock the demo’s next chapter</td></tr><tr><td>7 Record repair</td><td>Trusted reference beside selectable block cards</td><td>Explain the specific mismatch; preserve valid progress on retry</td></tr><tr><td>8 AI introduction</td><td>Training cards and a separate fresh test</td><td>Show an actual prediction, its limitations and a human decision</td></tr></tbody></table><p>These panels define states, not eight separate scenes. Reuse overlays and the same world wherever possible. A visually finished screen without its cancel, retry, error and resume paths is not a finished interaction.</p><h3 id="quest-log-and-encyclopedia">Quest log and encyclopedia<a class="header-anchor" href="#quest-log-and-encyclopedia" aria-label="Link to this section">​</a></h3><p>The log presents completed, current and locked main objectives chronologically. The active entry includes its resident, place, next action and progress. Optional discoveries are visually separate from required progression.</p><p>The encyclopedia uses four records: Discovered, Explained, Practiced and Demonstrated in a new situation. None is named “mastered.” Discovery adds a basic entry immediately. Identification adds meaning and a concise contextual prompt. A wrong answer must not hide the reference needed to learn.</p><p>No quiz appears after each coin or duplicate item. Group related discoveries and let the player consult entries in the field. Each entry includes what the concept does, an island example, one common misconception and the relevant activity.</p><h2 id="44-sound-design">4.4 Sound design<a class="header-anchor" href="#44-sound-design" aria-label="Link to this section">​</a></h2><p>Use quiet island ambience, light mechanical cues and clear confirmation sounds. Give purchase review, confirmation, invalid action and restoration distinguishable sounds without alarm-heavy punishment. Music should not compete with reading.</p><p>The milestone needs a small licensed or original sound set, volume controls and a silent-play path. Voice acting, adaptive scores and unique tracks for every station are not required. Document the license and source of every shipped sound; concept images do not authorize third-party audio reuse.</p><p>&lt;!-- page --&gt;</p><h1 id="5-mechanics">5 Mechanics<a class="header-anchor" href="#5-mechanics" aria-label="Link to this section">​</a></h1><h2 id="51-quests-and-dialogue">5.1 Quests and dialogue<a class="header-anchor" href="#51-quests-and-dialogue" aria-label="Link to this section">​</a></h2><p>Quest states are Locked → Available → Active → Ready to report → Completed. A quest can skip Ready to report when its completion occurs at a station. Each transition has a prerequisite, an action, a success response and a save boundary.</p><table><thead><tr><th>Situation</th><th>Required rule</th></tr></thead><tbody><tr><td>Early pickup</td><td>Record it once and count it when the relevant quest becomes active</td></tr><tr><td>Repeated report</td><td>Replay feedback if helpful; never repeat a one-time reward</td></tr><tr><td>Wrong answer</td><td>Show a hint or counterexample; retain the item and allow retry</td></tr><tr><td>Modal open</td><td>Suspend world input so one tap cannot both answer and move</td></tr><tr><td>Interrupted scene</td><td>Reload the last committed quest state and reconstruct world changes</td></tr><tr><td>New content</td><td>Preserve completed objective/version records; explicitly map the next required quest</td></tr></tbody></table><p>Dialogue should explain a decision in short pieces, not deliver an entire chapter before the player can act. Narrative choices may change feedback, but branching relationship systems and punishments for offending NPCs are outside scope.</p><h2 id="52-wallet-and-purchase">5.2 Wallet and purchase<a class="header-anchor" href="#52-wallet-and-purchase" aria-label="Link to this section">​</a></h2><p><img src="/Chainy-Docs/attachments/docs/media/gdd/gameplay-first/web3-purchase.png" alt="Wallet purchase concept"></p><p><em>Reference sequence: 12 coins, price 8, fee 1, total 9, remaining 3. Generated UI labels illustrate hierarchy; the rules below govern the implementation.</em></p><p>The wallet is an interface to account information and authorization. The ownership record belongs to the simulated ledger, not physically inside the wallet picture. An address is shareable receiving information; secret signing material is not.</p><p>Purchase states: Inspect → Review → Authorize → Pending → Confirmed or Failed. Review includes the recipient, item identifier, price, network fee and total. Cancelling before submission changes nothing. Confirmation changes balances, item ownership, activity and quest state atomically and once. Equipping an owned lantern does not submit another payment.</p><p>The milestone uses toy authorization checks clearly labelled a simulation. It does not need real seed generation, cryptographic signing, a public node or a blockchain SDK. If production later implements real hashes, use full hashes internally while shortening only their display. [S3–S5]</p><p>&lt;!-- page --&gt;</p><h2 id="53-economy-and-ownership-rules">5.3 Economy and ownership rules<a class="header-anchor" href="#53-economy-and-ownership-rules" aria-label="Link to this section">​</a></h2><p>Chain Coin is the fictional native currency used for the illustrated network fee. Builder Token is a fungible asset issued within that simulated network. Lantern #014 is a unique item whose token ownership is recorded; a separate receipt describes a transaction. Not every stackable supply needs an NFT. NFTs do not guarantee investment value or transfer every creative right. [S3, S4, S6]</p><p>For the first purchase, the learner starts with 12 Chain Coins and spends exactly 9 including the fee. Failed review checks charge nothing. Later lessons may illustrate an executed failed transaction consuming a fee, but must distinguish that from a pre-submission rejection. Movement, reading, viewing balances and ordinary equipment use are free. [S4]</p><p>The full exchange uses a displayed fixed teaching quote, with input, output, fee and post-trade balances. Show that swapping assets differs from buying a tool. Prevent a required quest from becoming unwinnable because all fee currency was exchanged. No speculative prices, scarcity manipulation or real-money purchase is needed.</p><h3 id="smart-contract-interaction">Smart contract interaction<a class="header-anchor" href="#smart-contract-interaction" aria-label="Link to this section">​</a></h3><p>A full repair agreement exposes the condition, trigger and result: “Required supplies received AND valid workshop completion evidence submitted AND reward not already claimed.” The player invokes the claim. A completion terminal supplies the in-game evidence; the program does not magically observe a real bridge or workshop.</p><p>An unmet condition explains what is missing. The condition is rechecked at commit time. A repeated claim returns Already claimed without another reward. A purchase can use a simpler conditional program before this broader quest is built. This is a teaching simulation, not executable Solidity or a deployed contract. [S5]</p><h3 id="seed-phrase-recovery">Seed phrase recovery<a class="header-anchor" href="#seed-phrase-recovery" aria-label="Link to this section">​</a></h3><p>In the full version, Sean helps secure a game-only backup before a later recovery exercise. Never scatter secret words as public treasure or ask the learner to enter a real wallet secret. Use an unmistakable “Practice backup — not a real wallet” screen and bounded fictional symbols or words.</p><p>Recovery restores access to the same simulated account and its existing ownership records; it does not mint a second lantern or reset balances. The fictional backup is unrelated to the student voucher, learner identity, teacher PIN or actual device save. A lost phone’s unsynced progress cannot be recovered by this lesson mechanic.</p><p>The first milestone can explain backup safety through dialogue, but that does not count as an implemented hands-on seed-recovery mechanic.</p><p>&lt;!-- page --&gt;</p><h2 id="54-blockchain-inspection-and-repair">5.4 Blockchain inspection and repair<a class="header-anchor" href="#54-blockchain-inspection-and-repair" aria-label="Link to this section">​</a></h2><p><img src="/Chainy-Docs/attachments/docs/media/gdd/gameplay-first/blockchain-repair.png" alt="Local ledger repair concept"></p><p><em>Reference interaction: inspect a trusted checkpoint, link the display blocks and reject changed data. The plate shows two placement slots for readability; the proposed core scenario uses three subsequent blocks. A/B/C are symbolic reference labels, not cryptographic hashes.</em></p><p>The core repair uses a known starting checkpoint and three subsequent display blocks. Each block exposes its identifier, previous reference and a concise record summary. One record refers to the actual lantern purchase. One block may contain several transactions, so the interface must not teach a universal one-transaction-per-block rule.</p><p>The learner selects a block, inspects its evidence and places it. A mismatch explains which reference failed. In the tamper case, the damaged display changes the price from 8 to 6; the trusted record still says 8. Restore from the verified source rather than asking the learner to arbitrarily edit the accepted payment.</p><p>The full version adds stale-node synchronization and candidate-transaction checks for authorization, balance, ownership and replay. A network decision is simulated separately; one player clicking Approve is not real consensus. Nodes and validators are related roles, not synonyms. [S7, S8]</p><p>The mining station is a separate proof-of-work comparison: vary a nonce, search for a hash meeting a toy target and show that verification is quicker than the search. Bound the demonstration and CPU work. Do not turn mining into hitting a rock or imply that the main proof-of-stake network also mines its blocks. [S8, S9]</p><p>The beacon’s restoration condition is a valid local reconstruction against the scenario’s trusted reference. It is not a claim that every real node must always be online and identical at the same instant.</p><p>&lt;!-- page --&gt;</p><h2 id="55-ai-teaching-and-testing">5.5 AI teaching and testing<a class="header-anchor" href="#55-ai-teaching-and-testing" aria-label="Link to this section">​</a></h2><p><img src="/Chainy-Docs/attachments/docs/media/gdd/gameplay-first/ai-training.png" alt="AI training and test concept"></p><p><em>Reference interaction: separate labelled examples from new test cases, show advisory predictions and preserve human review. The left panel shows labels already selected; the playable version must offer both choices first. The panels are separate screens, not simultaneous phone UI. Artwork does not establish model accuracy.</em></p><p>Use a small, curated synthetic dataset. Proposed features are known recipient, amount relative to usual activity and permission type. Each card also has story evidence so the learner is not labelling blindly. Labels mean Routine and Needs review, not guaranteed safe and criminal.</p><p>A candidate three-nearest-neighbor model compares normalized features and takes a label vote. Define ties, missing features and very unfamiliar cases as Review. The exact feature encoding and distance rule need a small prototype; the acceptance requirement is that changing relevant training labels or examples can change predictions on held-out requests. Do not display a vote fraction as a calibrated confidence percentage.</p><p>A proposed teaching set contains six examples, a separate four-case practice set and a reserved four-case final set. These counts are content-production starting points, not statistical validation. Practice feedback can guide corrections; final-set labels must not influence training before the recorded first final attempt. Replays become practice and must not be described as fresh independent tests. [S10]</p><p>Include counterexamples with sufficient context: a large approved workshop purchase, and a small request for inappropriate permission. A fresh final scenario should test the learner’s reasoning, not whether the bot can be forced to score perfectly.</p><p>For the later assistant activity, bundle authored responses and clearly label them simulated. A learner supplies goal, context and constraints, then opens records to verify a plausible answer. Prompt context is not retraining, and an AI text token is not a blockchain asset token. Later dispatch is a bounded scripted agent workflow: observe, propose, ask permission, act and inspect. It is not evidence that ordinary pathfinding has learned a model. [S11]</p><p>&lt;!-- page --&gt;</p><h2 id="56-coverage-of-all-twelve-requested-concepts">5.6 Coverage of all twelve requested concepts<a class="header-anchor" href="#56-coverage-of-all-twelve-requested-concepts" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Concept</th><th>Full hands-on mechanic</th><th>November boundary</th></tr></thead><tbody><tr><td>Cryptocurrency</td><td>Earn and budget fictional Chain Coin</td><td>CORE reward and purchase</td></tr><tr><td>Blockchain</td><td>Inspect own record and reconstruct local sequence</td><td>CORE bounded repair</td></tr><tr><td>Exchange</td><td>Preview and swap coin for Builder Tokens</td><td>FULL; explanation is not hands-on completion</td></tr><tr><td>Gas fee</td><td>Review fee separately from price</td><td>CORE purchase; advanced failure-fee lesson later</td></tr><tr><td>Keys</td><td>Share address; authorize with protected signing control</td><td>CORE toy signing interaction; not real key management</td></tr><tr><td>Mining and validators</td><td>Compare nonce search with distinct candidate-validation workflow</td><td>FULL; only basic verification in core</td></tr><tr><td>NFT</td><td>Obtain numbered equipment and inspect ownership</td><td>CORE Lantern #014</td></tr><tr><td>Smart contract</td><td>Inspect a purchase condition; later invoke a repair claim</td><td>CORE simple purchase condition; FULL external-evidence claim</td></tr><tr><td>Token</td><td>Spend issued Builder Tokens distinct from native currency</td><td>FULL</td></tr><tr><td>Wallet</td><td>Check balance, items, activity and authorization</td><td>CORE compact wallet</td></tr><tr><td>Seed phrase</td><td>Recover access with a previously protected fictional backup</td><td>FULL</td></tr><tr><td>Node</td><td>Compare and synchronize local simulated copies</td><td>CORE reference copy; FULL stale-node repair</td></tr></tbody></table><p>This table is a scope map, not a “concepts completed” percentage. Some concepts have an introductory action in the core and a substantial later exercise. Counting all twelve as complete because their names appear in a menu would misrepresent the result.</p><h2 id="57-supporting-quizzes-and-mini-games">5.7 Supporting quizzes and mini-games<a class="header-anchor" href="#57-supporting-quizzes-and-mini-games" aria-label="Link to this section">​</a></h2><p>Quiz prompts follow a relevant explanation or action. Use one concise identification question, a decision during use, and a new example at a milestone. Incorrect answers give explanations without taking essential coins. Record first response, hint use and eventual success separately when that evidence is needed.</p><p>Wordle supports vocabulary and definitions; it is not a substitute for using a concept. Its dictionary, word length, repeated-letter feedback and attempts require a rules sheet. BlockMatch remains the established matching/cascade activity until its own objective and educational relation are approved. Do not silently replace it with the new ledger-ordering exercise.</p><p>Quiz can reuse the dialogue/choice interface in the core. Standalone Wordle and BlockMatch remain in the full design but are proposed deferrals from November 10. Sherwin must explicitly approve any change to school-required modes. Completion of a spelling or matching puzzle must not be reported as proof of understanding blockchain or AI.</p><p>&lt;!-- page --&gt;</p><h2 id="58-local-state-and-implementation-boundaries">5.8 Local state and implementation boundaries<a class="header-anchor" href="#58-local-state-and-implementation-boundaries" aria-label="Link to this section">​</a></h2><p>Only one activity owns gameplay input at a time: exploration, dialogue, purchase, record repair or AI exercise. Opening a modal releases movement. A pending commit blocks repeated confirmation; closing a panel does not cancel a transaction already committed.</p><p>Reuse the existing controller and dialogue. Reconcile new quest, simulation and save responsibilities with Christian’s actual Game Manager, Progress Manager, Database Manager, event and scene interfaces. Do not begin with a replacement framework or new service platform.</p><p>SQLite remains the local store. Minimum persistent gameplay state includes profile ID, build/content/schema versions, active/completed quests, discovered entries, inventory and balances, ledger state, world restoration flags and relevant activity checkpoints. These are proposed record needs, not verified table definitions.</p><p>For a purchase or reward, balance, ownership, quest and ledger changes must succeed together. Use a stable action identifier to make duplicate taps and repeated resume handling harmless. Confirm “Saved” only after the database confirms success. Test interrupted commits, no-space failures, force-close and relaunch with synthetic profiles.</p><p>Data-heavy systems are deferred, but postponing save design until after all quests would be a delivery risk. The smallest reliable save is part of the first complete loop.</p><h2 id="59-later-teacher-and-distribution-service">5.9 Later teacher and distribution service<a class="header-anchor" href="#59-later-teacher-and-distribution-service" aria-label="Link to this section">​</a></h2><p>The full product retains Teacher/Student entry, developer-issued teacher vouchers, one online teacher activation, offline student pairing, a protected dashboard and local collection for approximately 20–40 personal student phones. Teachers later upload individual learner-coded results; names and the identity mapping remain with the teacher.</p><p>Separate three payloads: logical learning records, compatible content packages and signed Android app updates. They require different validation, retry and recovery rules. A teacher dashboard shows last received data, not live progress while phones are disconnected. Student devices are not nodes in the fictional blockchain lesson.</p><p>Nearby Connections or a local Wi-Fi session are candidates requiring device prototypes. No promise is made that 40 phones connect simultaneously, that updates are silent, or that SQLite itself provides synchronization. These capabilities are outside the November gameplay commitment. [S12, S13]</p><p>Do not collect real learner records in an improvised developer service. School authorization, receiving account, purpose, retention and deletion rules remain prerequisites. Demo tests use synthetic codes. A data-collection or school-evaluation obligation must be resolved with the adviser, not silently removed because services are deferred.</p><p>&lt;!-- page --&gt;</p><h1 id="6-characters">6 Characters<a class="header-anchor" href="#6-characters" aria-label="Link to this section">​</a></h1><p><img src="/Chainy-Docs/attachments/docs/media/gdd/gameplay-first/characters.png" alt="Explorer Sean Matthew and Lee character concepts"></p><p><em>Proposed character family: the Explorer and three variants of a reusable robot body. Names and Explorer identity are established; guide badges and accent colors remain design options. Match production proportions consistently across all scenes.</em></p><h2 id="61-explorer">6.1 Explorer<a class="header-anchor" href="#61-explorer" aria-label="Link to this section">​</a></h2><p>The Explorer is the player-controlled blue-haired character in yellow clothing. Use the existing movement and dialogue assets where suitable. The character helps residents and gains access to tools and restored locations, not combat power or speculative wealth.</p><p>Minimum animation states are idle, walk, interact and a short completion reaction. Equipment such as the lantern should attach consistently to the existing rig. Movement, interface focus and equipment state must agree when a dialogue closes or a scene resumes.</p><h2 id="62-guides-and-residents">6.2 Guides and residents<a class="header-anchor" href="#62-guides-and-residents" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Character</th><th>Function</th><th>Distinguishing visual cue</th><th>Teaching behavior</th></tr></thead><tbody><tr><td>Sean</td><td>Web3 arrival and economy guide</td><td>Wallet/book badge, warm station accents</td><td>Explains a practical need before introducing terminology</td></tr><tr><td>Matthew</td><td>Blockchain beacon guide, formerly Blocky</td><td>Linked-block badge, cyan record station</td><td>Asks for the reference or evidence behind a repair</td></tr><tr><td>Lee</td><td>AI assistance guide, formerly Aira</td><td>Example-card badge; a distinct restrained accent</td><td>Invites predictions, tests and admission of uncertainty</td></tr><tr><td>Residents</td><td>Give restoration requests and consequences</td><td>Reusable silhouettes and context props</td><td>Explain why the requested action matters</td></tr></tbody></table><p>Guide appearance variants are proposals for owner review. The guide names are confirmed. Reusing the existing friendly screen-faced robot base reduces model, rig and animation work; a new human character for every name is not assumed.</p><p>The NPC Sean and the team member Sean are different roles. Documentation ownership does not imply a character portrayal.</p><h2 id="63-character-scope">6.3 Character scope<a class="header-anchor" href="#63-character-scope" aria-label="Link to this section">​</a></h2><p>No combat animation, hostile reputation, daily routine simulation, creature ecology or elaborate pathfinding is required. Residents can remain at readable interaction points. A dispatch bot can use a short scripted path later without being presented as the learning model itself.</p><p>Dialogues should be encouraging but specific: identify the mistaken assumption and explain the correction. Avoid calling a learner unintelligent, punishing an incorrect answer with lost progress, or treating a prediction as certain because a friendly robot says it.</p><p>&lt;!-- page --&gt;</p><h1 id="7-project-plan-and-november-10-feasibility">7 Project plan and November 10 feasibility<a class="header-anchor" href="#7-project-plan-and-november-10-feasibility" aria-label="Link to this section">​</a></h1><h2 id="71-review-of-the-previous-output">7.1 Review of the previous output<a class="header-anchor" href="#71-review-of-the-previous-output" aria-label="Link to this section">​</a></h2><p>The earlier proposal is coherent as a full-product direction: the Web3 action creates a meaningful record, Blockchain makes that record inspectable, and AI teaches judgment over its use. The best parts to preserve are visible restoration, repeated use of the same lantern transaction, evidence-based repair, and the distinction between practice and independent learning evidence.</p><p>Its main delivery problem is breadth. It adds a quest runtime, inventory, simulated economy, safe transactions, ledger repair, training/test activity, several new UI families and dependable persistence, while also proposing school authorization, peer transfer, analytics, content distribution and upload. Those are not all supplied by movement, dialogue or SQLite.</p><p>The owner’s latest evidence is <strong>movement and dialogue only</strong>. Earlier repository statements about other components being in progress are not treated as playable acceptance evidence. The actual Unity version, current revision, Android APK, database integration and representative phones still need verification.</p><h3 id="verdict">Verdict<a class="header-anchor" href="#verdict" aria-label="Link to this section">​</a></h3><p><strong>A substantial gameplay slice by November 10 is plausible but high risk. “At least 50 percent of the entire earlier proposal” is not a defensible commitment today.</strong> Scope must be fixed and tested before a percentage can be claimed.</p><p>Recommended commitment: W01–W04 plus B01–B03 and the demo B07 restoration, with local saves, contextual Quiz prompts and a compact Android UI. Recommended stretch: A01–A03 using the same card/panel components. Retain exchange, Builder Tokens, full contract claims, seed recovery, mining/validator comparison, AI assistant/agent work and standalone Wordle/BlockMatch for later gates.</p><p>This is a genuine change from “all twelve concepts deeply playable now.” It preserves them in the full design without claiming the smaller milestone implements them all. If an adviser requires three playable subject modules, move the small AI chapter into required scope and reduce Web3/Blockchain content or renegotiate the target; do not quietly show concept art as a functioning AI module.</p><h2 id="72-what-50-percent-would-require">7.2 What 50 percent would require<a class="header-anchor" href="#72-what-50-percent-would-require" aria-label="Link to this section">​</a></h2><p>For an internal gameplay percentage, freeze the full deliverable baseline and agree weights for functional systems, content depth, usability and verified quality before evaluating the build. Record accepted evidence against that baseline. Do not choose weights afterwards to make the result reach 50.</p><p>For the school’s requirement, obtain its actual calculation and named criteria. The documented 60 percent pre-final requirement and eight-criterion quality rating cannot be converted into a completion percentage by counting chapters or tasks. November 10’s requested 50 percent is therefore an aspiration, not a demonstrated school result.</p><p>The concrete demo below remains useful even if no percentage is approved: earn → buy → confirm ownership → restore → repair a local record → save → relaunch. It lets the team demonstrate working behavior instead of an unverifiable number.</p><p>&lt;!-- page --&gt;</p><h2 id="73-capacity-and-effort-estimate">7.3 Capacity and effort estimate<a class="header-anchor" href="#73-capacity-and-effort-estimate" aria-label="Link to this section">​</a></h2><p>There are 19 calendar dates from October 23 through November 10 inclusive, or 13 weekdays. The developer’s stated maximum of 16–18 hours per day gives 304–342 nominal available hours across all 19 dates. This is arithmetic, not a forecast of productive output; it excludes interruptions, school/travel commitments, integration, rework and recovery.</p><p>Plan the first pass around 6–8 focused technical hours per available day and protect testing time. On all 19 dates that is 114–152 hours; on weekdays alone it is 78–104 hours. The November 3–6 beta, if retained, consumes availability and must be subtracted from these figures. UI/art availability has not been provided.</p><p>The following are order-of-magnitude estimates, not measured productivity or commitments. They assume the existing movement/dialogue work on Android, access to the actual source, reusable UI, simple placeholder art, one local profile, a small deterministic simulation and no networking. They include developer integration of separately supplied UI/art, but not creation of all production assets.</p><table><thead><tr><th>Work package</th><th style="text-align:right;">Focused lead-dev hours</th><th>Dependencies and completion evidence</th></tr></thead><tbody><tr><td>Android baseline and state/save scaffold</td><td style="text-align:right;">10–16</td><td>Named APK; synthetic profile survives exit and relaunch</td></tr><tr><td>Quest, interaction and inventory loop</td><td style="text-align:right;">12–20</td><td>Pickup, report, one-time reward and scene state reload correctly</td></tr><tr><td>Wallet, purchase and workshop restoration</td><td style="text-align:right;">18–28</td><td>Exact fee arithmetic; atomic ownership/payment; no duplicate reward</td></tr><tr><td>Bounded block ordering and altered-record case</td><td style="text-align:right;">12–20</td><td>Trusted-reference explanation and recoverable wrong placement</td></tr><tr><td>Shared UI/content integration and unlocks</td><td style="text-align:right;">8–14</td><td>Usable panels; demo quest list; no circular gate</td></tr><tr><td>Android regression and recovery testing</td><td style="text-align:right;">16–24</td><td>Save/resume, interruption, repeat-tap and low-device checks</td></tr><tr><td>Core subtotal</td><td style="text-align:right;">76–122</td><td>W01–W04 and bounded Blockchain demo</td></tr><tr><td>Contingency at approximately 25 percent</td><td style="text-align:right;">19–31</td><td>Unknown code condition and rework, not extra features</td></tr><tr><td>Core planning envelope</td><td style="text-align:right;">95–153</td><td>Conditional target; re-estimate after the first accepted loop</td></tr><tr><td>AI training/test stretch including contingency</td><td style="text-align:right;">20–35 additional</td><td>Reused card UI, data-dependent model, separate fresh final cases</td></tr></tbody></table><p>Indicative parallel supply needs: 12–24 focused hours for UI layouts/assets, 12–24 for a reusable art kit and scene dressing, and 8–16 for reviewed instructional copy and QA cases. These are separate lane estimates, not confirmed team availability, and cannot be added to Christian’s implementation capacity. If those handoffs are unavailable, the technical path expands or visuals remain provisional.</p><p>The 95–153-hour core overlaps the 114–152-hour all-days planning envelope but exceeds much of the weekday-only envelope. Thus the core is conditional, and the AI addition is clearly high risk. This comparison is more useful than assuming 16–18 hours every day guarantees success.</p><p>&lt;!-- page --&gt;</p><h2 id="74-milestones-and-dependency-gates">7.4 Milestones and dependency gates<a class="header-anchor" href="#74-milestones-and-dependency-gates" aria-label="Link to this section">​</a></h2><p>The existing project baseline fixes a November 3–6 beta and November 21 pre-final. Whether the beta has moved was asked but is not yet confirmed. This schedule preserves it unless the owner changes it explicitly.</p><table><thead><tr><th>Window</th><th>Priority and gate</th><th>Failure response</th></tr></thead><tbody><tr><td>Oct 23–24</td><td>Verify source/Android build; one pickup, reward, save and reload</td><td>Stop expansion; repair foundation before more screens</td></tr><tr><td>Oct 25–28</td><td>Complete W01–W04 with temporary art and exact transaction rules</td><td>Remove optional content; keep the complete restoration loop</td></tr><tr><td>Oct 29–30</td><td>Integrate bounded Blockchain repair only if Web3 is stable; freeze beta candidate</td><td>Ship a clearly limited Web3 demo if repair is not ready</td></tr><tr><td>Oct 31–Nov 2</td><td>Device tests, instructions, known issues and synthetic rehearsal</td><td>Fix blockers; no new gameplay subsystem</td></tr><tr><td>Nov 3–6</td><td>Existing school beta, if still scheduled</td><td>Collect approved evidence; do not assume these are full coding days</td></tr><tr><td>Nov 7–8</td><td>Fix observed failures; add AI only if core remains stable and capacity is real</td><td>Defer AI implementation rather than mislabel scripted results</td></tr><tr><td>Nov 9–10</td><td>Final regression and gameplay milestone demonstration</td><td>Report accepted and missing scope honestly</td></tr><tr><td>Nov 11–16</td><td>Stabilize chosen build and complete manuscript evidence</td><td>Admit no broad teacher-service platform unless separately rebaselined</td></tr><tr><td>Nov 17–20</td><td>Rehearsal, recovery drill and release freeze</td><td>Fix only release-blocking defects</td></tr><tr><td>Nov 21</td><td>Pre-final demonstration</td><td>Use the tested build and disclosed limitations</td></tr></tbody></table><p>If the beta moves to November 10, use November 3–6 for integration and testing, not an automatic expansion of scope. The schedule is a recommended replacement for missed internal targets, not a claim that earlier October milestones were achieved.</p><h3 id="critical-dependency-chain">Critical dependency chain<a class="header-anchor" href="#critical-dependency-chain" aria-label="Link to this section">​</a></h3><p>Verified Android build → reliable quest save → complete Web3 purchase/restoration → shared ledger data → bounded Blockchain repair → optional AI lesson → integrated regression → demonstration.</p><p>Art, copy and UI may proceed in parallel after the interaction fields and states are frozen. Multiple contributors do not remove the single-developer integration bottleneck. AI-generated designs reduce illustration time; they do not implement Unity interactions or validate learning outcomes.</p><h3 id="stop-rules">Stop rules<a class="header-anchor" href="#stop-rules" aria-label="Link to this section">​</a></h3><p>If no saved end-to-end quest works by October 28, reduce to one polished restoration quest and replan. If transaction duplication, save loss or progression dead ends remain, do not begin the AI stretch. Do not spend the final test window adding exchange, teacher networking or a new UI framework.</p><p>&lt;!-- page --&gt;</p><h2 id="75-ownership-and-handoffs">7.5 Ownership and handoffs<a class="header-anchor" href="#75-ownership-and-handoffs" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Lane</th><th>Owner</th><th>Required output to the next lane</th></tr></thead><tbody><tr><td>Scope and learning-game decisions</td><td>Sherwin</td><td>Approve core boundary, mini-game deferral, date changes and milestone interpretation</td></tr><tr><td>Game code, persistence, builds and integration</td><td>Christian</td><td>Named revision/APK, state contract, reproducible technical tests</td></tr><tr><td>Art assets</td><td>Luis</td><td>Reusable imported kit, source/provenance and scene previews</td></tr><tr><td>Authored project documentation and learning copy</td><td>Sean</td><td>Approved quest text, concepts, questions, acceptance cases and manuscript links</td></tr><tr><td>Game UI implementation</td><td>Miguel</td><td>Panels and input/error states conforming to the technical interface</td></tr></tbody></table><p>Each work card has one accountable owner. Separate the UI handoff from code integration and the design decision from document authorship. This edition proposes work packets; it creates no issue, changes no task status and publishes no board changes.</p><h3 id="review-findings-from-the-project-skills">Review findings from the project skills<a class="header-anchor" href="#review-findings-from-the-project-skills" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Review lens</th><th>Result applied in this edition</th></tr></thead><tbody><tr><td>Scope and dependency planning</td><td>Core, stretch and later-service boundary; capacity ranges and explicit dependency gates</td></tr><tr><td>GDD requirements and learning design</td><td>Observable actions, responses, retries and learning checks rather than definition-only fetch quests</td></tr><tr><td>Simulation accuracy</td><td>Local ledger repair, distinct mining/validation, advisory AI, fictional secrets and no real funds</td></tr><tr><td>Architecture and Unity delivery</td><td>Reuse existing movement/dialogue; verify actual Android build; define state/save ownership first</td></tr><tr><td>Gameplay implementation</td><td>Deterministic bounded scenarios and duplicate-safe actions; no code changes implied by this design</td></tr><tr><td>Asset and UI pipeline</td><td>Reusable kit, fixed isometric presentation, mobile overlays and concept-versus-production distinction</td></tr><tr><td>Android performance</td><td>Named-device profiling before support claims; preserve QA time</td></tr><tr><td>Offline evidence</td><td>Keep local saves now, defer transfer/upload; learner records separate from fictional transactions</td></tr><tr><td>QA, defense and release</td><td>Reproducible checks, truthful scope reporting, preserved pre-final and handover requirements</td></tr></tbody></table><p>The fourteen named project skills informed these decisions; they are review lenses, not independent human approvals. The visual swarm supplies concept assets only. Sherwin still approves scope, Christian validates implementation facts, and Sean reconciles the adopted edition into project documentation.</p><p>&lt;!-- page --&gt;</p><h2 id="76-acceptance-and-device-checks">7.6 Acceptance and device checks<a class="header-anchor" href="#76-acceptance-and-device-checks" aria-label="Link to this section">​</a></h2><table><thead><tr><th>ID</th><th>Test</th><th>Passing result</th></tr></thead><tbody><tr><td>GP01</td><td>Start a new local demo profile offline</td><td>Web3 opens; other demo chapters have clear gates</td></tr><tr><td>GP02</td><td>Open dialogue while moving</td><td>Movement stops; closing returns control without an unintended action</td></tr><tr><td>GP03</td><td>Collect an item early, answer incorrectly and return</td><td>Item persists; explanation remains accessible; no progression dead end</td></tr><tr><td>GP04</td><td>Earn the resident reward twice</td><td>Exactly 12 coins are granted once</td></tr><tr><td>GP05</td><td>Buy Lantern #014 from 12 coins</td><td>Price 8 plus fee 1 leaves 3; ownership and record agree</td></tr><tr><td>GP06</td><td>Cancel review or double-tap confirmation</td><td>Cancel changes nothing; repeated confirmation commits at most once</td></tr><tr><td>GP07</td><td>Equip the lantern and restore the workshop</td><td>No extra gas; restoration and quest completion save together</td></tr><tr><td>GP08</td><td>Force-close and relaunch after checkpoints</td><td>Balance, inventory, records, quests and restored scene agree</td></tr><tr><td>GP09</td><td>Simulate a save failure or insufficient storage</td><td>No false Saved message; last good state retained; recovery offered</td></tr><tr><td>GP10</td><td>Place blocks by color/time rather than valid references</td><td>Invalid sequence rejected with a precise explanation</td></tr><tr><td>GP11</td><td>Compare altered 6-coin payment with verified 8-coin source</td><td>Learner repairs local copy; cannot overwrite trusted source</td></tr><tr><td>GP12</td><td>Finish demo Web3 and Blockchain chapters</td><td>Correct next demo chapter unlocks; completed worlds remain accessible</td></tr><tr><td>GP13</td><td>Train, change examples and test new AI cases</td><td>Outputs depend on examples; practice and final records remain distinct</td></tr><tr><td>GP14</td><td>Reject unsupported AI advice</td><td>No automatic spend; evidence and human review remain available</td></tr></tbody></table><p>GP13 applies only if the AI stretch is delivered; GP14 belongs to the later assistant/dispatch release. “Not implemented” is a valid status and must not be replaced with a fabricated pass. For executed checks, record the build, content version, device, steps, expected/actual result and evidence.</p><p>The device specification remains a target: 4 GB physical RAM, 64 GB total storage, ARM64, OpenGL ES 3.2 or Vulkan 1.1 and an entry-to-midrange GPU. Android 11+ is the provisional test interpretation; Android 10 compatibility remains unverified. Total storage is not the app’s allowed footprint.</p><p>Proposed performance target: a readable, responsive scene around 30 fps on the selected lower-end test phone. Measure loading, sustained scene performance, memory, heat, suspend/resume and storage use before publishing support claims. Verify permissions, ARM64 packaging, signing and save-preserving updates on real hardware.</p><h3 id="demonstration-and-release-evidence">Demonstration and release evidence<a class="header-anchor" href="#demonstration-and-release-evidence" aria-label="Link to this section">​</a></h3><p>Prepare one named APK, a short installation guide, synthetic demo profile, known-issues list and reproducible restoration demonstration. Show offline play and a relaunch that preserves the result. Keep signing credentials outside repositories. Do not present the teacher dashboard, generated art or future service diagrams as a live feature.</p><p>&lt;!-- page --&gt;</p><h1 id="8-references-and-template-adaptation">8 References and template adaptation<a class="header-anchor" href="#8-references-and-template-adaptation" aria-label="Link to this section">​</a></h1><h2 id="81-main-structural-reference">8.1 Main structural reference<a class="header-anchor" href="#81-main-structural-reference" aria-label="Link to this section">​</a></h2><p>The supplied 27-page <em>Games Design Document — Project Vanishing</em> is the main organizational reference. Its structure is applied as follows, with PDF page numbers counted from the first page:</p><table><thead><tr><th>Reference pages</th><th>Reference element</th><th>Chainy adaptation</th></tr></thead><tbody><tr><td>4</td><td>Game, narrative and objective briefs</td><td>Section 1 defines the educational restoration adventure</td></tr><tr><td>5</td><td>Gameplay and control layout</td><td>Section 2 uses mobile touch and fixed isometric controls</td></tr><tr><td>6–7</td><td>World map and location descriptions</td><td>Section 3 defines three compact, ordered worlds</td></tr><tr><td>7–13</td><td>Art, GUI, storyboard, sample narrative and sound</td><td>Section 4 plus W03 example dialogue; concept sheets illustrate interfaces</td></tr><tr><td>13–18</td><td>Quest/dialogue, progression, AI/pathing and economy</td><td>Section 5 substitutes educational systems and explicitly excludes combat/reputation</td></tr><tr><td>19–21</td><td>Character mechanics, development and animation</td><td>Section 6 keeps Explorer/guides and minimal reusable animation</td></tr><tr><td>22–26</td><td>Project plan, Gantt and sprint reports</td><td>Section 7 gives dated gates, dependencies, estimates and acceptance evidence</td></tr><tr><td>27</td><td>References and bibliography</td><td>Sections 8–9 identify the design and technical sources</td></tr></tbody></table><p>The reference’s table of contents and body numbering diverge around Mechanics: Weapons appears as 5.2 in the body, while later systems shift. This edition uses its own consistent numbering. It does not reproduce the sample’s “BREIF” typo, control-direction inconsistency or example student progress reports as Chainy facts.</p><p>The source’s combat, hostility, class development, first-person perspective and medieval story are examples, not instructions to add them to this educational mobile game. No source artwork is copied into the new visual pack.</p><h2 id="82-project-evidence-and-limitations">8.2 Project evidence and limitations<a class="header-anchor" href="#82-project-evidence-and-limitations" aria-label="Link to this section">​</a></h2><p>Direct owner decisions govern this edition; Section 1 and the later-service boundary retain them. The latest report of movement and dialogue being playable supersedes older “in progress” descriptions. Project sources are listed under S2. No APK, performance or learner test was performed for this document; estimates are not measured results.</p><p>&lt;!-- page --&gt;</p><h1 id="9-bibliography">9 Bibliography<a class="header-anchor" href="#9-bibliography" aria-label="Link to this section">​</a></h1><h3 id="design-and-project-sources">Design and project sources<a class="header-anchor" href="#design-and-project-sources" aria-label="Link to this section">​</a></h3><p>S1. Supplied <em>Games Design Document — Project Vanishing</em>, 27-page PDF, inspected October 22, 2026. Main structure and presentation reference; not a Chainy implementation source.</p><p>S2. Chainy project documents and owner decisions, inspected October 22, 2026: current baseline, GDD, technical design, requirements, active plan, hardware validation, art/UI brief, offline-data plan, learning and evaluation documents; plus <em>Chainy Gameplay Validation and Proposed Journey</em> from this conversation. Version conflicts are resolved in favor of the latest direct owner decision.</p><h3 id="primary-technical-sources">Primary technical sources<a class="header-anchor" href="#primary-technical-sources" aria-label="Link to this section">​</a></h3><p>S3. Ethereum documentation, <a href="https://ethereum.org/developers/docs/accounts/">Accounts</a>. Supports account, address, key and wallet distinctions; Chainy’s authorization remains fictional.</p><p>S4. Ethereum documentation, <a href="https://ethereum.org/developers/docs/gas/">Gas and fees</a>. Supports transaction-cost distinctions; Chain Coin and the 1-coin tutorial fee are authored game rules.</p><p>S5. Ethereum documentation, <a href="https://ethereum.org/developers/docs/smart-contracts/">Smart contracts</a>. Supports triggered program behavior and external-information limits; no deployed contract is required.</p><p>S6. Ethereum documentation, <a href="https://ethereum.org/nft/">Non-fungible tokens</a>. Supports unique token/ownership distinctions; the lantern is an educational example.</p><p>S7. Ethereum documentation, <a href="https://ethereum.org/developers/docs/nodes-and-clients/">Nodes and clients</a>. Supports node roles; classroom devices are not used as actual blockchain nodes.</p><p>S8. Ethereum documentation, <a href="https://ethereum.org/developers/docs/consensus-mechanisms/pos/">Proof of stake</a>. Supports the distinction between validator participation and a single learner’s approval.</p><p>S9. Ethereum documentation, <a href="https://ethereum.org/developers/docs/consensus-mechanisms/pow/">Proof of work</a>. Supports the separate bounded mining comparison.</p><p>S10. Google Machine Learning Crash Course, <a href="https://developers.google.com/machine-learning/crash-course/overfitting/dividing-datasets">Training, validation and test sets</a>. Supports separating practice and fresh tests; a tiny teaching dataset does not establish real-world reliability.</p><p>S11. Google Machine Learning Crash Course, <a href="https://developers.google.com/machine-learning/crash-course/llm/transformers">Large language models</a>. Supports token-prediction and limitation explanations; the offline assistant uses clearly labelled authored responses.</p><p>S12. Google, <a href="https://developers.google.com/nearby/connections/overview">Nearby Connections overview</a>. Candidate transport for the later school service, subject to actual device and integration tests.</p><p>S13. Android documentation, <a href="https://developer.android.com/studio/publish/app-signing">App signing</a>. Supports the distinction between a content package and a signed app update.</p><p>Technical references inform accuracy, not implementation status. The numerical economy, quest names, dataset sizes, effort ranges and milestone boundaries are Chainy design proposals. The visual pack’s accompanying notes retain generation prompts and limitations for production handoff.</p></div>',1)])])}const m=t(i,[["render",o]]);export{u as __pageData,m as default};
